// The CARD grammar, as a reader your own resolver can use.
// Generated by flux-grammar-atlas. Nothing here is reserved by anyone else:
// these labels mean exactly what this file says, in your resolver only.

export const LABELS = [
  {
    "label": "W",
    "name": "record kind",
    "payload": "closed-set",
    "values": [
      "MESH",
      "TEX",
      "PLACE"
    ]
  },
  {
    "label": "R",
    "name": "view",
    "payload": "lowercase-alphanumeric"
  },
  {
    "label": "C",
    "name": "content id",
    "payload": "lowercase-hex",
    "minLength": 64,
    "evenLength": true
  },
  {
    "label": "A",
    "name": "byte count",
    "payload": "digits"
  },
  {
    "label": "I",
    "name": "texture slot",
    "payload": "digits"
  },
  {
    "label": "X",
    "name": "x",
    "payload": "lowercase-alphanumeric",
    "pattern": "^(0|m?[1-9][0-9]{0,8}|m?(0|[1-9][0-9]{0,8})p[0-9]{0,5}[1-9])$"
  },
  {
    "label": "Y",
    "name": "y",
    "payload": "lowercase-alphanumeric",
    "pattern": "^(0|m?[1-9][0-9]{0,8}|m?(0|[1-9][0-9]{0,8})p[0-9]{0,5}[1-9])$"
  },
  {
    "label": "Z",
    "name": "z",
    "payload": "lowercase-alphanumeric",
    "pattern": "^(0|m?[1-9][0-9]{0,8}|m?(0|[1-9][0-9]{0,8})p[0-9]{0,5}[1-9])$"
  },
  {
    "label": "D",
    "name": "height",
    "payload": "lowercase-alphanumeric",
    "pattern": "^(0|m?[1-9][0-9]{0,8}|m?(0|[1-9][0-9]{0,8})p[0-9]{0,5}[1-9])$"
  },
  {
    "label": "U",
    "name": "turn",
    "payload": "lowercase-alphanumeric",
    "pattern": "^(0|m?[1-9][0-9]{0,8}|m?(0|[1-9][0-9]{0,8})p[0-9]{0,5}[1-9])$"
  }
];

const RULES = {
  "closed-set": (v, l) => l.values.includes(v),
  "lowercase-alphanumeric": (v, l) => (l.pattern ? new RegExp(l.pattern) : /^[a-z0-9]+$/).test(v),
  "lowercase-hex": (v, l) => /^[0-9a-f]+$/.test(v) && (!l.evenLength || v.length % 2 === 0),
  "digits": v => /^[0-9]+$/.test(v),
};

// Longest label first: a box belongs to the longest label it starts with.
const BY_LENGTH = [...LABELS].sort((a, b) => b.label.length - a.label.length);

export function readBox(box) {
  const label = BY_LENGTH.find((l) => box.startsWith(l.label));
  if (!label) throw new Error(`no label in the CARD grammar starts "${box}"`);
  const value = box.slice(label.label.length);
  if (!RULES[label.payload](value, label)) throw new Error(`${label.label}: "${value}" is not a valid ${label.name}`);
  return { label: label.label, name: label.name, value };
}

export function readRecord(record) {
  return record.split('-').map(readBox);
}

// Try it: readRecord("WMESH-Rauth-Caaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa-A31904")
